    if (user.isLegacyHash) {
        const legacyDigest = legacySha256(plainPassword);
        const isValid = await argon2.verify(user.passwordHash, legacyDigest);

        // Replace the wrapped hash with a direct Argon2id hash now that we know the real password
        if (isValid) {
