const argon2 = require("argon2");
const crypto = require("crypto");

// Hash a new password with Argon2id, which salts automatically and is deliberately slow
// so stolen hashes are expensive to crack
async function hashPassword(plainPassword) {
    const passwordHash = await argon2.hash(plainPassword, { type: argon2.argon2id });
    return passwordHash;
}

// Check a login attempt against the stored hash, handling users still on the old SHA-256 scheme
// whose hashes were wrapped in Argon2 during migration
async function verifyPassword(plainPassword, userRecord) {
    let passwordToCheck = plainPassword;

    // Wrapped users had argon2(sha256(password)) stored, so we recreate the inner SHA-256 first
    if (userRecord.isLegacyWrapped) {
        passwordToCheck = crypto.createHash("sha256").update(plainPassword).digest("hex");
    }

    const isMatch = await argon2.verify(userRecord.passwordHash, passwordToCheck);
    return isMatch;
